export interface AlternativeProduct {
  rank: number;
  name: string;
  bestFor: string;
  pros: string[];
  cons: string[];
  pricing: string;
  rating: number;
}

export interface AlternativeFaq {
  question: string;
  answer: string;
}

/**
 * Editorial decision content rendered on an alternatives page when present.
 * Optional — legacy entries render exactly as before. Content added here is
 * per-entry editorial analysis; templates only provide structure.
 */
export type AlternativeEvidenceLabel = 'documentation-analysis' | 'hands-on-testing';

export interface AlternativeDecisionFactor {
  factor: string;
  contextA: string;   // what the original tool does
  contextB: string;   // what the alternative does better / trade-off
  whenItMatters: string;
}

export interface AlternativeEditorial {
  /** Why the original tool's limits push someone to switch, and who should switch. */
  decisionSummary: string;
  /** 2-4 concrete limits of the original tool that drive the switch. */
  originalToolLimits: string[];
  decisionFactors: AlternativeDecisionFactor[];
  bestFor: string;    // who this alternatives set fits
  notFor: string;     // who should NOT switch away from the original
  migrationCost: string; // what switching sacrifices (data, workflow, price)
  scenarios: { scenario: string; who: string; reason: string }[];
  evidenceLabel: AlternativeEvidenceLabel;
  evidenceNote?: string;
}

export interface AlternativeEntry {
  slug: string;
  title: string;
  toolName: string;
  category: string;
  color: string;
  description: string;
  intro: string;
  alternatives: AlternativeProduct[];
  whyChoose: string[];
  faqs: AlternativeFaq[];
  internalLinks: string[];
  lastUpdated: string;
  testingDuration: string;
  authorSlug: string;
  /** Optional editorial decision content (Phase 2 enhancement). */
  editorial?: AlternativeEditorial;
}

